example.code:
# WRONG — behind a CDN every consumer shares one bucket (r7)
limit_req_zone $binary_remote_addr zone=api_limit:10m rate=10r/s;

# RIGHT — key on the consumer identity the gateway resolved
limit_req_zone $http_x_consumer_id zone=api_limit:10m rate=10r/s;
proxy_set_header X-Request-ID $request_id;
proxy_read_timeout 5s;
